	SELECT ADN_PK, 'ADN'
	FROM inserted
GO
CREATE TRIGGER UNDGSubstanceADN_Version_Update
	ON UNDGSubstanceADN
	FOR Update
	AS
	UPDATE version SET RVC_IsPublished = 0, RVC_LastEditedUser = dbo.GetUserId()
	FROM RefDbVersionControl version
	JOIN inserted ON ADN_PK = RVC_ParentPK
	WHERE RVC_IsPublished = 1
GO
